import { readFileSync } from "fs";

const [s, t] = readFileSync(0, "utf8").trim().split("\n");

// 各文字の出現回数を数え、S で足して T で引く
function same(x: string, y: string): boolean {
  if (x.length !== y.length) return false;
  const count = new Array(26).fill(0);
  for (const c of x) count[c.charCodeAt(0) - 97]++;
  for (const c of y) count[c.charCodeAt(0) - 97]--;
  return count.every((v) => v === 0);
}
console.log(same(s, t) ? "Yes" : "No");
